import java.util.*;

class Solution {
    public boolean parseBoolExpr(String expression) {
        Deque<Character> st = new ArrayDeque<>();
        for (int i = 0; i < expression.length(); i++) {
            char c = expression.charAt(i);
            if (c == ',') continue;
            if (c != ')') {
                st.push(c);
            } else {
                List<Character> seen = new ArrayList<>();
                while (!st.isEmpty() && st.peek() != '(') {
                    seen.add(st.pop());
                }
                if (!st.isEmpty()) st.pop(); // remove '('
                char op = st.pop();
                char res = 'f';
                if (op == '!') {
                    res = (seen.get(0) == 't' ? 'f' : 't');
                } else if (op == '&') {
                    boolean allTrue = true;
                    for (char x : seen) {
                        if (x == 'f') { allTrue = false; break; }
                    }
                    res = allTrue ? 't' : 'f';
                } else if (op == '|') {
                    boolean anyTrue = false;
                    for (char x : seen) {
                        if (x == 't') { anyTrue = true; break; }
                    }
                    res = anyTrue ? 't' : 'f';
                }
                st.push(res);
            }
        }
        return st.peek() == 't';
    }
}

var parseBoolExpr = function(expression) {
    const stack = [];
    for (const c of expression) {
        if (c === ',') continue;
        if (c !== ')') {
            stack.push(c);
        } else {
            const seen = [];
            while (stack.length > 0 && stack[stack.length - 1] !== '(') {
                seen.push(stack.pop());
            }
            stack.pop(); // remove '('
            const op = stack.pop();
            let res = 'f';
            if (op === '!') {
                res = seen[0] === 't' ? 'f' : 't';
            } else if (op === '&') {
                res = seen.includes('f') ? 'f' : 't';
            } else if (op === '|') {
                res = seen.includes('t') ? 't' : 'f';
            }
            stack.push(res);
        }
    }
    return stack[stack.length - 1] === 't';
};
